<?php
chdir(dirname(__DIR__));
 session_start();require_once 'dbconn.php';require_once 'includes/functions.php';requireRole(['School Registrar','System Administrator']);$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();try{$id=(int)($_POST['request_id']??0);$q=$pdo->prepare("SELECT r.request_id,u.user_id,u.role FROM password_reset_requests r JOIN users u ON u.user_id=r.user_id WHERE r.request_id=? AND r.request_status='Pending'");$q->execute([$id]);$r=$q->fetch();if(!$r)throw new Exception('Request is no longer pending.');if($r['role']==='System Administrator')throw new Exception('Administrator password cannot be reset here.');$pdo->beginTransaction();$pdo->prepare("UPDATE users SET password_hash=?,must_change_password=1,account_status='Active' WHERE user_id=?")->execute([password_hash('1',PASSWORD_DEFAULT),$r['user_id']]);$pdo->prepare("UPDATE password_reset_requests SET request_status='Completed',reviewed_by=?,reviewed_at=NOW() WHERE request_id=?")->execute([$_SESSION['user_id'],$id]);$pdo->prepare("INSERT INTO user_notifications(user_id,title,message,notification_type,related_url) VALUES(?,?,?,?,?)")->execute([$r['user_id'],'Password reset completed','Your temporary password is now 1. Change it after logging in.','Password Reset','login.php']);$pdo->commit();$msg='Password reset to 1. The user must change it after login.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}
$rows=$pdo->query("SELECT r.*,u.username,u.role,COALESCE(CONCAT_WS(' ',s.first_name,s.last_name),CONCAT_WS(' ',sp.first_name,sp.last_name)) full_name,s.student_lrn FROM password_reset_requests r JOIN users u ON u.user_id=r.user_id LEFT JOIN students s ON s.user_id=u.user_id LEFT JOIN staff_profiles sp ON sp.user_id=u.user_id ORDER BY FIELD(r.request_status,'Pending','Completed','Rejected'),r.requested_at DESC")->fetchAll();require 'includes/header.php';?><div class="page-heading"><div><h1>Password Reset Requests</h1><p>Reset the requested account to temporary password 1.</p></div></div><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Name</th><th>Username / LRN</th><th>Role</th><th>Requested</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['full_name']??'—')?></td><td><?=e($r['student_lrn']??$r['username'])?></td><td><?=e($r['role'])?></td><td><?=e($r['requested_at'])?></td><td><?=e($r['request_status'])?></td><td><?php if($r['request_status']==='Pending'):?><form method="post" onsubmit="return confirm('Reset password to 1?')"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="request_id" value="<?=$r['request_id']?>"><button class="btn btn-sm btn-primary">Reset to 1</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>
